    # 7. React Router & Navigation - 30 Qs
    rt_items = [
        ("What is React Router?", "React Router is the standard client-side routing library for React applications, allowing navigation between views without full page reloads.", "Easy", "Concept", "import { BrowserRouter, Routes, Route } from 'react-router-dom';", "What is client-side routing?"),
        ("How does client-side routing differ from traditional server-side routing?", "Server routing requests a brand new HTML document on every link click (reloads page). Client-side routing intercepts clicks, updates the browser URL via History API, and swaps components without reloads.", "Easy", "Comparison", "", "What is BrowserRouter?"),
        ("What is <BrowserRouter> in React Router?", "BrowserRouter is a top-level provider component that connects React Router to the browser's HTML5 History API (pushState, replaceState, popstate).", "Easy", "Concept", "<BrowserRouter>\n  <App />\n</BrowserRouter>", "What other routers exist in React Router?"),
        ("What is the difference between BrowserRouter and HashRouter?", "BrowserRouter uses standard clean URLs (/about) requiring server fallback configuration. HashRouter uses URL hash (#/about) for legacy servers that cannot handle client-side routing.", "Intermediate", "Comparison", "example.com/about vs example.com/#/about", "Why does BrowserRouter require server configuration?"),
        ("Why does refreshing a page on /about throw a 404 error on standard static servers using BrowserRouter?", "The web server looks for a physical file /about/index.html on disk. Servers must be configured to redirect all incoming requests to index.html (SPA fallback).", "Intermediate", "Scenario", "", "How do you configure this on Netlify or Vercel?"),
        ("How do you configure Netlify or Apache for SPA client-side routing?", "On Netlify, add a _redirects file: /* /index.html 200. On Vercel, configure rewrites in vercel.json.", "Easy", "Practical", "/*    /index.html   200", "What are <Routes> and <Route> in React Router v6?"),
        ("What is the syntax of <Routes> and <Route> in React Router v6?", "<Routes> wraps route definitions. <Route path='/path' element={<Component />} /> maps a URL path to a React component.", "Easy", "Practical", "<Routes>\n  <Route path=\"/\" element={<Home />} />\n  <Route path=\"/about\" element={<About />} />\n</Routes>", "How does Route syntax differ from React Router v5?"),
        ("What is the difference between <Link> and regular <a> tags in React Router?", "<a> triggers a full browser page refresh. <Link to='/about'> intercepts the click and updates the URL client-side via history.pushState without reloading the page.", "Easy", "Comparison", "<Link to=\"/dashboard\">Dashboard</Link>", "Why should you never use <a> for internal links in a React SPA?"),
        ("What is the <NavLink> component in React Router?", "NavLink is a specialized <Link> that knows whether its target URL is currently active, adding an 'active' CSS class or accepting an isActive callback for styling.", "Easy", "Practical", "<NavLink to=\"/home\" className={({ isActive }) => isActive ? 'nav-active' : ''}>Home</NavLink>", "How is NavLink used in navigation bars?"),
        ("What does the useNavigate hook do in React Router v6?", "useNavigate returns a navigate function that lets you change routes programmatically (e.g. after form submission or login).", "Easy", "Practical", "const navigate = useNavigate();\nnavigate('/dashboard');", "How do you go back to the previous page with useNavigate?"),
        ("How do you navigate back to the previous page using useNavigate?", "Pass -1: navigate(-1); (equivalent to clicking the browser back button).", "Easy", "Practical", "navigate(-1); // Back one step\nnavigate(1); // Forward one step", "How do you replace history instead of pushing?"),
        ("How do you replace the current history entry using navigate?", "Pass { replace: true }: navigate('/login', { replace: true });.", "Easy", "Practical", "navigate('/login', { replace: true });", "Why is replace: true useful after login?"),
        ("What is the useParams hook in React Router?", "useParams returns an object of key/value pairs of dynamic URL path parameters defined in the route: <Route path='/users/:id' element={<User />} />.", "Easy", "Practical", "const { id } = useParams();\nconsole.log(id);", "How do you define multiple path parameters?"),
        ("How do you define dynamic path parameters in a route?", "Prefix segment with a colon: <Route path='/products/:category/:productId' element={<Product />} />.", "Easy", "Practical", "<Route path=\"/users/:userId\" element={<Profile />} />", "What does useParams return if no params exist?"),
        ("What is the useSearchParams hook in React Router v6?", "useSearchParams reads and modifies URL query strings (?sort=asc&page=2), returning [searchParams, setSearchParams] like useState.", "Intermediate", "Practical", "const [searchParams, setSearchParams] = useSearchParams();\nconst page = searchParams.get('page');", "How do you update query parameters?"),
        ("How do you update query parameters with setSearchParams?", "setSearchParams({ page: 2, filter: 'active' });", "Easy", "Practical", "setSearchParams({ tab: 'settings' });", "Does updating query parameters reload the page?"),
        ("What is the useLocation hook in React Router?", "useLocation returns the current location object containing pathname, search, hash, and state.", "Easy", "Practical", "const location = useLocation();\nconsole.log(location.pathname); // '/dashboard'", "How do you pass data through route state?"),
        ("How do you pass data through route state during navigation?", "Pass { state: data } to Link or navigate: navigate('/summary', { state: { orderId: 42 } }). Read via useLocation().state.", "Intermediate", "Practical", "navigate('/success', { state: { paid: true } });\n// In target:\nconst { state } = useLocation();", "Is location.state visible in the browser URL address bar?"),
        ("Is location.state visible in the browser URL?", "No. location.state is stored in browser memory/session history and is completely invisible in the URL bar.", "Easy", "Concept", "", "What are nested routes in React Router v6?"),
        ("What are nested routes and what is the <Outlet> component in React Router v6?", "Nested routes render child routes inside a parent layout. The parent component uses <Outlet /> as a placeholder where matching child routes render.", "Intermediate", "Concept", "<Route path=\"/dashboard\" element={<DashboardLayout />}>\n  <Route path=\"analytics\" element={<Analytics />} />\n</Route>\n// Inside DashboardLayout:\nreturn <div><Sidebar /><Outlet /></div>;", "Why is <Outlet> powerful for dashboard layouts?"),
        ("What is an Index Route in React Router v6?", "An index route (<Route index element={<Home />} />) renders as the default child component inside an <Outlet> when the parent URL matches exactly.", "Intermediate", "Concept", "<Route path=\"/\" element={<Layout />}>\n  <Route index element={<Home />} />\n  <Route path=\"about\" element={<About />} />\n</Route>", "How does index route simplify defaults?"),
        ("How do you create a 404 Not Found catch-all route in React Router v6?", "Add <Route path='*' element={<NotFound />} /> at the end of your routes list. The asterisk wildcard matches any URL that wasn't matched above.", "Easy", "Practical", "<Route path=\"*\" element={<NotFound />} />", "Where should the * route be placed?"),
        ("How do you implement Protected Routes (Authentication guards) in React Router v6?", "Create a wrapper component that checks if user is logged in. If yes, return <Outlet />; if no, return <Navigate to='/login' replace />.", "Intermediate", "Scenario", "function ProtectedRoute({ isAuth }) {\n  return isAuth ? <Outlet /> : <Navigate to=\"/login\" replace />;\n}", "What does the <Navigate> component do?"),
        ("What does the <Navigate to='...' /> component do?", "It programmatically navigates to a new location when rendered (declarative navigation).", "Easy", "Concept", "<Navigate to=\"/dashboard\" replace />", "How does <Navigate> differ from useNavigate?"),
        ("Router MCQ: Which hook extracts dynamic URL path segments like /users/:id?", "Option C is correct. useParams() extracts URL parameters.", "Easy", "MCQ", "", {"A": "useRoute()", "B": "usePath()", "C": "useParams()", "D": "useQuery()"}, "C", "What does useSearchParams extract?"),
        ("Router MCQ: Which component acts as a placeholder for child routes inside a parent layout?", "Option B is correct. <Outlet /> renders child route elements.", "Easy", "MCQ", "", {"A": "<Children />", "B": "<Outlet />", "C": "<Portal />", "D": "<RouterView />"}, "B", "Where is Outlet placed?"),
        ("Router Debugging: Clicking a <Link to='/about'> causes a full page refresh. Why?", "The link was written as a regular <a href='/about'> HTML anchor tag instead of React Router's <Link to='/about'> component.", "Easy", "Debugging", "<Link to=\"/about\">About</Link>", "Why does <a> cause full refresh?"),
        ("Router Output: In <Route path='/user/:id' />, if URL is /user/42?tab=info, what does useParams() return?", "Output: { id: '42' }. Query string parameters are not included in useParams; use useSearchParams() for ?tab=info.", "Easy", "Output", "const { id } = useParams(); // { id: '42' }", "How do you get 'tab'?"),
        ("Router Coding: Write a Navbar with NavLinks for Home ('/'), Projects ('/projects'), and About ('/about').", "function Navbar() { return <nav><NavLink to='/'>Home</NavLink><NavLink to='/projects'>Projects</NavLink><NavLink to='/about'>About</NavLink></nav>; }", "Easy", "Coding", "function Navbar() {\n  return (\n    <nav className=\"nav-bar\">\n      <NavLink to=\"/\" end>Home</NavLink>\n      <NavLink to=\"/projects\">Projects</NavLink>\n      <NavLink to=\"/about\">About</NavLink>\n    </nav>\n  );\n}", "Why add the 'end' prop to Home NavLink?"),
        ("Why should the 'end' prop be added to Home <NavLink to='/' end>?", "Without 'end', '/' matches every single route because every route begins with '/', causing the Home link to be permanently styled active.", "Intermediate", "Concept", "", "What was this called in v5?")
    ]
