    # 10. Advanced React Patterns & React 18 - 55 Qs
    adv_items = [
        ("What is a Higher-Order Component (HOC) in React?", "An HOC is a pure function that takes a component as an argument and returns a new enhanced component (e.g. withAuth(Dashboard)).", "Intermediate", "Concept", "function withAuth(Component) {\n  return function(props) {\n    return isAuth ? <Component {...props} /> : <Login />;\n  };\n}", "Why have Custom Hooks largely replaced HOCs?"),
        ("Why have custom Hooks largely replaced Higher-Order Components in modern React?", "Custom Hooks share logic without adding extra wrapper layers to the component tree (eliminating 'wrapper hell') and avoid prop naming collisions.", "Intermediate", "Comparison", "", "What is the Render Props pattern?"),
        ("What is the Render Props pattern in React?", "A technique for sharing code between components using a prop whose value is a function returning React elements (e.g. <DataProvider render={data => <View data={data} />} />).", "Intermediate", "Concept", "<Mouse render={({ x, y }) => (\n  <h1>Mouse position: {x}, {y}</h1>\n)} />", "How do custom hooks compare to render props?"),
        ("What are Compound Components in React?", "A pattern where a group of related components work together sharing implicit state via Context (e.g. <Select><Select.Option /></Select> or <Tabs><Tab /></Tabs>).", "Intermediate", "Concept", "<Accordion>\n  <Accordion.Item title=\"Q1\">Answer 1</Accordion.Item>\n  <Accordion.Item title=\"Q2\">Answer 2</Accordion.Item>\n</Accordion>", "What makes compound components clean for design systems?"),
        ("What is Concurrent React (Concurrent Mode) in React 18?", "A foundational capability enabling React to prepare multiple versions of the UI simultaneously, pausing and resuming rendering work without blocking the main browser thread.", "Advanced", "Concept", "", "What is startTransition in React 18?"),
        ("What is startTransition in React 18 and when should it be used?", "startTransition marks a state update as non-urgent. Urgent updates (typing in an input) interrupt non-urgent transitions (filtering a 10,000-item list), keeping the UI responsive.", "Intermediate", "Performance", "import { startTransition } from 'react';\nstartTransition(() => {\n  setFilterQuery(value); // Non-urgent search filter\n});", "What is useTransition hook?"),
        ("What does the useTransition hook return?", "It returns [isPending, startTransition], where isPending is a boolean indicating whether the background transition is actively processing.", "Intermediate", "Practical", "const [isPending, startTransition] = useTransition();\n{isPending && <Spinner />}", "How does useTransition improve search inputs?"),
        ("What is useDeferredValue in React 18?", "useDeferredValue accepts a value and returns a deferred version of that value that lags behind urgent state updates.", "Intermediate", "Performance", "const deferredText = useDeferredValue(text);", "When would you choose useDeferredValue over useTransition?"),
        ("When should you choose useDeferredValue over useTransition?", "Use useTransition when you own the state setter call. Use useDeferredValue when receiving a value as a prop from an external parent and you want to defer rendering downstream children.", "Advanced", "Comparison", "", "What is React Suspense?"),
        ("What is React Suspense and what does it do?", "Suspense lets components 'wait' for something before rendering, displaying a fallback UI (like a loading skeleton) while code or data is loading.", "Easy", "Concept", "<Suspense fallback={<Skeleton />}>\n  <UserProfile />\n</Suspense>", "What triggers a Suspense boundary?"),
        ("What triggers a Suspense boundary?", "Throwing a Promise from a component or resource during render signals to Suspense that data or code is pending.", "Advanced", "Concept", "", "What is React.lazy() and how does it work with Suspense?"),
        ("How do you implement route-based code splitting using React.lazy and Suspense?", "Wrap dynamic component imports in React.lazy and wrap routes inside <Suspense fallback={<Loading />}>.", "Easy", "Practical", "const Dashboard = React.lazy(() => import('./Dashboard'));\n<Suspense fallback={<Spinner />}>\n  <Dashboard />\n</Suspense>", "What happens if a lazy component fails to load?"),
        ("What happens if a lazy-loaded chunk fails to download (e.g. offline user)?", "It throws a network loading error that is caught by the nearest Error Boundary.", "Intermediate", "Scenario", "", "What is ReactDOM.createRoot in React 18?",),
        ("What is ReactDOM.createRoot in React 18 and why was ReactDOM.render deprecated?", "createRoot creates the root container enabling all React 18 concurrent features and automatic batching. ReactDOM.render was the legacy synchronous API.", "Easy", "Concept", "const root = ReactDOM.createRoot(document.getElementById('root'));\nroot.render(<App />);", "Does React 18 enable concurrent features without createRoot?"),
        ("Can you use React 18 concurrent features with legacy ReactDOM.render?", "No! Using the legacy ReactDOM.render runs React 18 in backward-compatible legacy mode, disabling automatic batching and concurrent features.", "Intermediate", "Concept", "", "What is Server-Side Rendering (SSR) in React?"),
        ("What is Server-Side Rendering (SSR) in React?", "SSR renders the initial HTML markup of React components on the server before sending it to the client, improving First Contentful Paint (FCP) and SEO rankings.", "Intermediate", "Concept", "", "What is Hydration in React?"),
        ("What is Hydration in React SSR?", "Hydration is the process where client-side React attaches event listeners and state management to server-rendered HTML without recreating DOM nodes.", "Intermediate", "Concept", "", "What is a Hydration Mismatch error?"),
        ("What causes a Hydration Mismatch error in React?", "When the HTML rendered on the server differs from the HTML generated by the client during initial render (e.g. using window.innerWidth or Date.now() during render).", "Intermediate", "Debugging", "Text content does not match server-rendered HTML.", "How do you avoid hydration mismatch with dates?"),
        ("How do you avoid hydration mismatch for browser-specific data (like theme or dates)?", "Render a consistent placeholder on initial render, and update to client-specific values inside useEffect() on mount.", "Intermediate", "Practical", "const [mounted, setMounted] = useState(false);\nuseEffect(() => setMounted(true), []);\nif (!mounted) return null;", "Why does this eliminate the mismatch?"),
        ("What are React Server Components (RSC)?", "Server Components run exclusively on the server, have direct zero-latency access to databases, and send pure serialized JSON/HTML to the client with 0kb client bundle cost.", "Advanced", "Concept", "", "What is the difference between SSR and React Server Components (RSC)?"),
        ("What is the difference between traditional SSR and React Server Components?", "SSR generates HTML strings on the server and sends JavaScript for the entire page to hydrate. RSC never ships JS for server components to the browser, reducing bundle size permanently.", "Advanced", "Comparison", "", "What is the 'use client' directive in Next.js / modern React?"),
        ("What does the 'use client' directive indicate in modern React?", "'use client' at the top of a file marks the boundary between Server Components and Client Components, enabling interactive hooks (useState, useEffect, onClick).", "Easy", "Concept", "'use client';\nimport { useState } from 'react';", "Can a Server Component import a Client Component?"),
        ("Can a Server Component import a Client Component in modern React?", "Yes! Server Components can import and render Client Components freely.", "Easy", "Concept", "", "Can a Client Component import a Server Component directly?"),
        ("Can a Client Component directly import a Server Component?", "No. A Client Component cannot import a Server Component directly; however, it can accept and render a Server Component passed as 'children' or props.", "Advanced", "Concept", "<ClientContainer>{/* ServerComponent */}</ClientContainer>", "Why is this composition pattern powerful?"),
        ("What is the React Profiler API?", "The Profiler measures how often a React application renders and what the 'cost' of rendering is, helping identify rendering bottlenecks.", "Intermediate", "Performance", "<Profiler id=\"Navigation\" onRender={onRenderCallback}>\n  <Navigation />\n</Profiler>", "What are the arguments to onRenderCallback?"),
        ("What does the React Developer Tools Profiler tab show?", "It records component render durations, identifies which components re-rendered, and displays flame charts showing why each component rendered.", "Easy", "Practical", "", "What is the 'Highlight updates when components render' setting in React DevTools?"),
        ("What does 'Highlight updates when components render' in React DevTools do?", "It draws colored rectangles around DOM elements whenever their React component re-renders, making unnecessary re-renders immediately visible.", "Easy", "Practical", "", "Why is this helpful for performance tuning?"),
        ("Patterns MCQ: Which pattern allows sharing stateful logic across components without modifying component hierarchy?", "Option B is correct. Custom Hooks share logic cleanly without extra wrappers.", "Easy", "MCQ", "", {"A": "Higher-Order Components", "B": "Custom Hooks", "C": "Render Props", "D": "Mixins"}, "B", "Why are mixins deprecated?"),
        ("Patterns MCQ: What does useTransition return?", "Option A is correct. It returns [isPending, startTransition].", "Easy", "MCQ", "", {"A": "[isPending, startTransition]", "B": "[deferredValue, setValue]", "C": "[isReady, transition]", "D": "[loading, start]"}, "A", "What type is isPending?"),
        ("Patterns MCQ: What does createRoot replace in React 18?", "Option C is correct. createRoot replaces the deprecated ReactDOM.render.", "Easy", "MCQ", "", {"A": "React.createElement", "B": "ReactDOM.hydrate", "C": "ReactDOM.render", "D": "React.Component"}, "C", "Why was it replaced?"),
        ("Debugging: A component renders a live clock. The initial render shows server time, but the screen flashes client time with a console error. Why?", "Hydration mismatch: the server HTML and client initial render rendered different timestamps. Move live clock updating to useEffect.", "Intermediate", "Debugging", "useEffect(() => { setTime(Date.now()); }, []);", "How does useEffect prevent the hydration error?"),
        ("Coding: Write a Higher-Order Component withLogger(Component) that logs whenever the component renders.", "function withLogger(Wrapped) { return function(props) { useEffect(() => console.log('Rendered:', Wrapped.name)); return <Wrapped {...props} />; }; }", "Intermediate", "Coding", "function withLogger(WrappedComponent) {\n  return function WithLogger(props) {\n    console.log(`Rendering ${WrappedComponent.name || 'Component'}`);\n    return <WrappedComponent {...props} />;\n  };\n}", "How do you preserve ref with an HOC?"),
        ("How do you preserve refs when wrapping a component with an HOC?", "Wrap the returned component in React.forwardRef and pass the ref to the wrapped component: forwardRef((props, ref) => <Wrapped ref={ref} {...props} />).", "Advanced", "Practical", "", "Why do HOCs lose refs without forwardRef?"),
        ("What is Prop Types in React and why was it replaced by TypeScript in modern development?", "PropTypes checked prop types at runtime in development. TypeScript checks types statically at compile time before code ever runs in the browser.", "Easy", "Comparison", "", "What is the advantage of TypeScript over PropTypes?"),
        ("Why is TypeScript superior to PropTypes in React applications?", "TypeScript catches type mismatches instantly in the IDE before execution, provides autocompletion, refactoring safety, and has zero runtime performance overhead.", "Easy", "Concept", "", "What is React Fiber's priority scheduling?"),
        ("What is priority-based lane scheduling in React Fiber?", "Fiber assigns priority lanes to updates (Immediate, User-blocking, Normal, Low, Idle) to ensure urgent interactions (typing) are never delayed by low-priority updates (analytics).", "Advanced", "Concept", "", "How does lane scheduling prevent input lag?"),
        ("What is the difference between controlled vs uncontrolled form libraries in React (e.g. Formik vs React Hook Form)?", "Formik uses controlled components (re-renders on every keystroke). React Hook Form uses uncontrolled components via refs, re-rendering only when errors or validation state change, maximizing performance.", "Intermediate", "Comparison", "", "Why is React Hook Form faster for large forms?"),
        ("What is optimistic UI update in React?", "Updating the UI immediately on user action before the server responds, assuming success, and rolling back state only if the server returns an error.", "Intermediate", "Scenario", "setLiked(true); // Optimistic\ntry { await api.like(); } catch { setLiked(false); }", "Why do apps like Twitter and Instagram use optimistic updates?"),
        ("How do you implement an optimistic update in React?", "Immediately update local state on user action, then issue the API call. If the API fails, catch the error and revert the state back to the previous snapshot.", "Intermediate", "Practical", "", "What does useOptimistic hook do in React 19?",),
        ("What is the useOptimistic hook introduced in React 19?", "useOptimistic is a built-in React hook for managing optimistic state updates that automatically reverts to real state when asynchronous actions complete.", "Advanced", "Concept", "const [optimisticCount, setOptimistic] = useOptimistic(count);", "What hook manages form actions in React 19?"),
        ("What is the useActionState / useFormState hook in React 19?", "A hook that updates state based on the result of a form action: const [state, formAction, isPending] = useActionState(actionFn, initialState);.", "Advanced", "Concept", "", "How does React 19 simplify form submissions?"),
        ("How does React 19 simplify form handling with Actions?", "HTML <form action={asyncFn}> can accept async functions directly, managing loading states, error boundaries, and optimistic updates automatically.", "Advanced", "Concept", "", "What is the difference between React 18 and React 19 for ref props?"),
        ("How are 'ref' props handled on functional components in React 19 compared to React 18?", "In React 19, 'ref' is available as a standard prop directly on function components, deprecating the need for React.forwardRef().", "Intermediate", "Concept", "function MyInput({ ref, ...props }) { return <input ref={ref} {...props} />; }", "Why is removing forwardRef a huge developer experience win?"),
        ("What is the React Compiler (React Forget)?", "An experimental compiler by the React team that automatically memoizes values and functions at build-time, eliminating the manual need for useMemo, useCallback, and React.memo.", "Advanced", "Concept", "", "What problem does the React Compiler solve?"),
        ("What developer pain does the React Compiler solve?", "It frees developers from manually managing dependency arrays, preventing stale closures, and littering codebases with useMemo and useCallback.", "Advanced", "Concept", "", "Is React 100% backward compatible with legacy code?")
    ]
    for item in adv_items:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-react-{num}", num, "React", "Advanced Patterns & React 18", "Architecture & Advanced Patterns",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
